_PRE_REOPEN_CHECKPOINT_BYTES = __import__("base64").b64decode(_PRE_REOPEN_CHECKPOINT_B64)
_PRE_REOPEN_LEDGER_BYTES = __import__("base64").b64decode(_PRE_REOPEN_LEDGER_B64)
if V25.blob(_PRE_REOPEN_CHECKPOINT_BYTES) != EXACT_FROZEN_BLOBS[CHECKPOINT]:
    base.fail("v67 embedded pre-reopen checkpoint bytes do not match the pinned PRE blob")
if V25.blob(_PRE_REOPEN_LEDGER_BYTES) != EXACT_FROZEN_BLOBS[LEDGER]:
    base.fail("v67 embedded pre-reopen ledger bytes do not match the pinned PRE blob")


def _workflow_replacements(view: Any) -> dict[str, bytes]:
    replacements: dict[str, bytes] = {}
    for path in (FW, AW):
        data = view.read_bytes(path, base.MAX_POLICY_FILE_BYTES)
        predecessor = _v66_workflow_bytes(data, path)
        actual = V25.sha(predecessor)
        if actual != Q_WF[path]:
            base.fail(
                "v67 workflow does not reverse to exact canonical v66 predecessor: "
                f"{path} expected={Q_WF[path]} actual={actual}"
            )
        replacements[path] = predecessor
    return replacements


def _derive_candidate_workflow_hash(path: str) -> str:
    _workflow_replacements(raw_root)
    return V25.sha(raw_root.read_bytes(path, base.MAX_POLICY_FILE_BYTES))


WF = {
    FW: _derive_candidate_workflow_hash(FW),
    AW: _derive_candidate_workflow_hash(AW),
    CW: q.WF[CW],
}


def bootbase(view: Any) -> bool:
    return P not in V25.ps(view)


def req_v66(view: Any) -> None:
    for path, expected in ((q.P, V66_P_BLOB), (q.T, V66_T_BLOB)):
        if path not in V25.ps(view):
            base.fail(f"v67 candidate/base is missing frozen v66 predecessor: {path}")
        actual = V25.blob(view.read_bytes(path, base.MAX_POLICY_FILE_BYTES))
        if actual != expected:
            base.fail(
                f"frozen v66 predecessor drifted: {path}: "
                f"expected={expected} actual={actual}"
            )


def _project_for_v66(view: Any) -> Any:
    return _ProjectionView(view, _workflow_replacements(view), POLICY_FILES)


def _v66_views(candidate: Any, policy_base: Any) -> tuple[Any, Any]:
    projected_candidate = _project_for_v66(candidate)
    if bootbase(policy_base):
        return projected_candidate, policy_base
    return projected_candidate, _project_for_v66(policy_base)


def run_predecessor_selftests() -> None:
    """Run frozen v66's own self-tests once, under a v67->v66 workflow
    reversal, with `CHECKPOINT` and `LEDGER` both projected back to their
    pre-reopen bytes.

    This is the repair. v66's own version of this function projected only
    the workflow entrypoints, believing (per its own docstring, since
    corrected) that the reopened pair was not subject to any downstream
    frozen-content check - a belief this repair's own docstring records as
    false, with the exact two checks it is false against and the exact
    error each raised when tested directly.
    """
    workflow_reversal = _workflow_replacements(raw_root)
    docs_reversal = {
        CHECKPOINT: _PRE_REOPEN_CHECKPOINT_BYTES,
        LEDGER: _PRE_REOPEN_LEDGER_BYTES,
    }
    original_read_bytes = base.LocalRepositoryView.read_bytes

    def _v66_selftest_read_bytes(local_view: Any, relative: str, limit: int) -> bytes:
        if relative in workflow_reversal:
            data = workflow_reversal[relative]
            if len(data) > limit:
                base.fail(
                    f"v67 v66-selftest workflow projection exceeds read bound: {relative}"
                )
            return data
        if relative in docs_reversal:
            data = docs_reversal[relative]
            if len(data) > limit:
                base.fail(
                    "v67 v66-selftest pre-reopen documentation projection "
                    f"exceeds read bound: {relative}"
                )
            return data
        return original_read_bytes(local_view, relative, limit)

    base.LocalRepositoryView.read_bytes = _v66_selftest_read_bytes
    try:
        _call("v66 self-tests under v67->v66 workflow+docs reversal", q.selftest)
    finally:
        base.LocalRepositoryView.read_bytes = original_read_bytes


def _reopen_available(view: Any) -> bool:
    return q._reopen_available(view)


def _verify_reopen_candidate(candidate: Any, policy_base: Any) -> None:
    q._verify_reopen_candidate(candidate, policy_base)


def delta(candidate: Any, policy_base: Any) -> None:
    paths = V25.changed(V25.v24.v23, candidate, policy_base)

    if bootbase(policy_base):
        if paths != BOOT:
            if paths & BOOT:
                base.fail(
                    "v67 bootstrap delta must be exactly two v67 policy files plus two integrity workflows"
                )
            base.fail("v67 bootstrap base authorizes only exact v66 self-test-only repair activation")
        req_v66(candidate)
        req_v66(policy_base)
        return

    if paths & CONTROLLED_FILES:
        base.fail("canonical v67 policy files are frozen after activation")

    projected_candidate, projected_base = _v66_views(candidate, policy_base)
    q.delta(projected_candidate, projected_base)


def basectrl(candidate: Any, policy_base: Any) -> None:
    if not bootbase(policy_base):
        q.basectrl(*_v66_views(candidate, policy_base))
        return
    for path in sorted(base.BASE_CONTROLLED_PATHS):
        candidate_bytes = candidate.read_bytes(path, base.MAX_POLICY_FILE_BYTES)
        base_bytes = policy_base.read_bytes(path, base.MAX_POLICY_FILE_BYTES)
        if path in (FW, AW):
            if V25.sha(candidate_bytes) != WF[path] or V25.sha(base_bytes) != Q_WF[path]:
                base.fail(f"v67 bootstrap workflow drifted: {path}")
        elif candidate_bytes != base_bytes:
            base.fail(f"base-controlled policy/governance path changed: {path}")


def ext(candidate: Any, policy_base: Any, safe: Any) -> None:
    safe_paths = frozenset(safe)
    for path in sorted(CONTROLLED_FILES & safe_paths):
        if path not in V25.ps(candidate):
            base.fail(f"v67 controlled file missing: {path}")
        if bootbase(policy_base):
            if path in V25.ps(policy_base):
                base.fail(f"v67 controlled file unexpectedly exists in bootstrap base: {path}")
        elif path not in V25.ps(policy_base) or candidate.read_bytes(
            path, base.MAX_POLICY_FILE_BYTES
        ) != policy_base.read_bytes(path, base.MAX_POLICY_FILE_BYTES):
            base.fail(f"v67 steady-state controlled file drifted: {path}")

    rest = frozenset(safe_paths - CONTROLLED_FILES)
    if rest:
        projected_candidate, projected_base = _v66_views(candidate, policy_base)
        q.ext(projected_candidate, projected_base, rest)


def dext(candidate: Any, policy_base: Any) -> None:
    ext(candidate, policy_base, V25.extset(V25.topo()[3]))


def eext(candidate: Any, policy_base: Any) -> None:
    ext(candidate, policy_base, V25.extset(V25.topo()[4]))


def allowed(paths: Any, stage: str) -> None:
    remaining = set(paths) - CONTROLLED_FILES
    if remaining:
        q.allowed(remaining, stage)


def files(view: Any) -> None:
    q.files(_project_for_v66(view))
    approved = {
        P: raw_root.read_bytes(P, base.MAX_POLICY_FILE_BYTES),
        T: raw_root.read_bytes(T, base.MAX_POLICY_FILE_BYTES),
    }
    for path in sorted(CONTROLLED_FILES):
        if path not in V25.ps(view):
            base.fail(f"v67 controlled file missing: {path}")
        if V25.mode(view, path) != "100644":
            base.fail(f"v67 controlled file mode invalid: {path}")
        if view.read_bytes(path, base.MAX_POLICY_FILE_BYTES) != approved[path]:
            base.fail(f"v67 controlled file content drifted: {path}")


def verify_component_base(
    view: Any,
    paths: set[str],
    *,
    allow_core_main_change: bool,
) -> None:
    if _PREDECESSOR_COMPONENT_BASE is None:
        base.fail("v67 predecessor component-base hook unavailable")
    _call(
        "v67 predecessor component-base verifier",
        _PREDECESSOR_COMPONENT_BASE,
        _project_for_v66(view),
        set(paths) - CONTROLLED_FILES,
        allow_core_main_change=allow_core_main_change,
    )


def freeze_s1_007_state(candidate: Any, policy_base: Any) -> None:
    if _PREDECESSOR_FREEZE_S1 is None:
        base.fail("v67 predecessor S1 freeze hook unavailable")
    projected_candidate, projected_base = _v66_views(candidate, policy_base)
    _call(
        "v67 predecessor S1 state freeze",
        _PREDECESSOR_FREEZE_S1,
        projected_candidate,
        projected_base,
    )


def printer(stage: str, mode_: str) -> None:
    q.printer(stage, mode_)
    print("wepld_policy_successor_v67=S2_A009_SELFTEST_ONLY_REPAIR_NO_FUNCTIONAL_CHANGE")
    print(f"v67_authority={AUTH}")
    print(f"s2_implementation_authority_v67={S2_IMPLEMENTATION_AUTHORITY}")
    print(f"git_route_decision_v67={GIT_ROUTE_DECISION}")
    print(f"git_execution_authority_v67={GIT_EXECUTION_AUTHORITY}")
    print(f"network_authority_v67={NETWORK_AUTHORITY}")
    print(f"source_admission_v67={SOURCE_ADMISSION}")
    print(f"reopen_available_v67={_reopen_available(raw_root)}")
    print(f"next_authority_gate_v67={NEXT_AUTHORITY_GATE}")


def _chain() -> tuple[Any, ...]:
    return (q,) + q._chain()


def prepare_q() -> None:
    for module in _chain():
        current = dict(module.WF)
        if current not in (Q_WF, dict(WF)):
            base.fail(f"v67 predecessor workflow identity map drifted: actual={current}")
    for module in _chain():
        module.WF = dict(WF)


def overlay() -> None:
    shell, routing, _, desktop, execution = V25.topo()
    pairs = (
        (_attr(routing, "IMPL_REQUIRE_EXACT_DELTA", "routing hook"), delta),
        (base.compare_base_controlled, basectrl),
        (_attr(desktop, "verify_extension_controlled_paths", "desktop hook"), dext),
        (_attr(execution, "verify_extension_controlled_paths", "execution hook"), eext),
        (_attr(shell, "validate_allowed_paths", "allowed hook"), allowed),
        (_attr(shell, "verify_policy_files", "files hook"), files),
        (_attr(shell, "print_success", "printer hook"), printer),
        (_attr(execution, "_verify_component_base", "component-base hook"), verify_component_base),
        (_attr(execution, "freeze_s1_007_state", "S1 state freeze hook"), freeze_s1_007_state),
    )
    if any(actual is not expected for actual, expected in pairs):
        base.fail("v67 installed overlay drifted")
    if any(dict(module.WF) != dict(WF) for module in _chain()):
        base.fail("v67 workflow identity projection drifted")
    for name in _INHERITED_AUTHORITY_NAMES:
        if getattr(q, name) != globals()[name]:
            base.fail(f"v67 inherited authority drifted: {name}")
    if q.EXACT_FROZEN_BLOBS != EXACT_FROZEN_BLOBS:
        base.fail("v67 must not move the inherited reopen pins")


def install() -> None:
    global _INST, _PREDECESSOR_COMPONENT_BASE, _PREDECESSOR_FREEZE_S1
    if _INST:
        overlay()
        return

    q.install()

    shell, routing, _, desktop, execution = V25.topo()
    pairs = (
        (_attr(routing, "IMPL_REQUIRE_EXACT_DELTA", "v66 routing hook"), q.delta),
        (base.compare_base_controlled, q.basectrl),
        (_attr(desktop, "verify_extension_controlled_paths", "v66 desktop hook"), q.dext),
        (_attr(execution, "verify_extension_controlled_paths", "v66 execution hook"), q.eext),
        (_attr(shell, "validate_allowed_paths", "v66 allowed hook"), q.allowed),
        (_attr(shell, "verify_policy_files", "v66 files hook"), q.files),
        (_attr(shell, "print_success", "v66 printer"), q.printer),
        (_attr(execution, "_verify_component_base", "v66 component-base hook"), q.verify_component_base),
        (_attr(execution, "freeze_s1_007_state", "v66 S1 state freeze hook"), q.freeze_s1_007_state),
    )
    if any(actual is not expected for actual, expected in pairs):
        base.fail("v67 predecessor hook drifted")

    _PREDECESSOR_COMPONENT_BASE = _attr(
        execution, "_verify_component_base", "predecessor component-base hook"
    )
    _PREDECESSOR_FREEZE_S1 = _attr(
        execution, "freeze_s1_007_state", "predecessor S1 state freeze hook"
    )

    prepare_q()
    desktop_extensions = frozenset(set(V25.extset(desktop)) | set(CONTROLLED_FILES))
    execution_extensions = frozenset(set(V25.extset(execution)) | set(CONTROLLED_FILES))
    _bind(desktop, "EXTENSION_CONTROLLED_PATHS", desktop_extensions, "v67 desktop registration")
    _bind(execution, "EXTENSION_CONTROLLED_PATHS", execution_extensions, "v67 execution registration")
    _bind(routing, "IMPL_REQUIRE_EXACT_DELTA", delta, "v67 routing hook")
    base.compare_base_controlled = basectrl
    _bind(desktop, "verify_extension_controlled_paths", dext, "v67 desktop hook")
    _bind(execution, "verify_extension_controlled_paths", eext, "v67 execution hook")
    _bind(shell, "validate_allowed_paths", allowed, "v67 allowed hook")
    _bind(shell, "verify_policy_files", files, "v67 files hook")
    _bind(shell, "print_success", printer, "v67 printer hook")
    _bind(execution, "_verify_component_base", verify_component_base, "v67 component-base hook")
    _bind(execution, "freeze_s1_007_state", freeze_s1_007_state, "v67 S1 state freeze hook")
    _INST = True
    overlay()


def selftest() -> None:
    from wepld_s2_a009_selftest_repair_v67_selftest import run

    run()


def main(argv: list[str]) -> int:
    try:
        if argv and argv[0] == "selftest":
            selftest()
            return 0
        install()
        if argv and argv[0] == "verify-candidate-local":
            parser = argparse.ArgumentParser(add_help=False)
            parser.add_argument("--root", required=True)
            parser.add_argument("--policy-base-root", required=True)
            parser.add_argument("--policy-base-sha", required=True)
            args = parser.parse_args(argv[1:])
            return int(
                _call(
                    "candidate-local verifier",
                    V25.CAND,
                    args.root,
                    args.policy_base_root,
                    args.policy_base_sha,
                )
            )
        return int(_call("runtime verifier", V25.RUNTIME, argv))
    except base.PolicyError as exc:
        print(f"wepld integrity verification: FAIL: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
